CREATE TABLE app_settings (
      key TEXT PRIMARY KEY,
      value TEXT
    );

CREATE TABLE ev_pitch_links (
                source_key TEXT PRIMARY KEY, pending_pitch_id INTEGER NOT NULL, pitch_clip_id INTEGER
            );

CREATE TABLE ev_swing_links (
                source_key TEXT PRIMARY KEY, pending_swing_id INTEGER NOT NULL, swing_clip_id INTEGER
            , ev_hit_id INTEGER);

CREATE TABLE pitch_video_sources (
    id TEXT PRIMARY KEY, original_file_name TEXT NOT NULL, stored_file_name TEXT NOT NULL,
    sha256 TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  );

CREATE TABLE teams (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    description TEXT
);
